Curve_FE04C9=Curve_Muting_Cutoff_Q16_128
Curve_FE05C9=Curve_Muting_Cutoff_Q13_128
Curve_Log2_251=Curve_Position_Log2Period_251
ExpCurve_0_to_0x80=Curve_Exp2Gain_U8_128
LinCoef_FE0096=LinCoef_Position_KeyRamp_Q5_128
LinCoef_FE0116=LinCoef_Fitting_KeyRamp_Q5_128
LinCoef_FE0196=LinCoef_Muting_KeyRamp_Q5_128
LinCoef_FE0216=LinCoef_SubGain_KeyRamp_Q5_128
Table_FDFF96=Table_Muting_CutoffFloor_ByKeyZone_256
